if not QuestEcho or not QuestEcho.DataModules then return end
if GetLocale() ~= "esES" then return end

QuestEchoData.GossipLookupByNPCID = {
	[68] = {
		["Grifos, ¿eh? En realidad, nunca me han atraído estas bestias. Cada uno con sus cosas.\n\nPuedes encontrar a Dungar Tragolargo en la muralla del Distrito de Mercaderes."] = "258744fe85450f544093d5fd17856341",
		["¿Quieres darte un paseo en grifo? Dungar tiene estos pájaros en la muralla del Distrito de Mercaderes. ¡No olvides agarrarte fuerte!"] = "7df84a254c23565acaa7fc468ead3ab2",
		["Ahhh, lo que buscas es el Centro de Viajeros de Ventormenta. Es el primer edificio a la izquierda si atraviesas las puertas delanteras del Valle de los Héroes."] = "646cbbc2bf91bdaa020beb25f4e0a678",
		["¿Eres hijo de la naturaleza? Entonces no tienes que buscar en la Poza de la Luna que está en el parque."] = "a63f0a77a472eab18caf48ea8320d27e",
		["¡Todo indica que quieres hablar con Maginor Dumas! Casi siempre está en el Sagrario del Mago, en el Barrio de los Magos. Por supuesto, nunca sabes hacia qué portal viajan esos magos, ni en qué momento lo hacen."] = "fa0d9c855011039c74c70b23db0b82ea",
		["Sugeriría que buscaras en la Catedral de la Luz, en la Plaza de la Catedral."] = "7c15eb60533829779dc9fd0c60d26a6a",
		["Si quieres encontrar pícaros, ve al Casco Antiguo. Está en la zona noreste de Ventormenta."] = "cd52082b0fdc76c7dded230c974a2ebf",
		["Busca por el Casco Antiguo y en el cuartel o en la taberna El Cerdo Borracho. Si vas a la taberna, no olvides probar algunas de las mejores cervezas. Ponen en evidencia la mala calidad de los brebajes de los enanos, te lo digo yo."] = "c621f0b9a4a6a6290dd5972a302122fc",
		["¿$GOtro:Otra; negociante, eh? Puedes encontrar la casa de subastas en el Distrito de Mercaderes. Cerca del banco."] = "3b18fc0710278c6aa12fb30a85999aaf",
		["La contaduría de Ventormenta se encuentra junto a las puertas principales del Distrito de los Mercaderes de Ventormenta. Y si te cansas de contar tu dinero no olvides visitar la posada La Rosa Áurea para tomar un trago."] = "554b8726d09d342022c5c7eaf5a9818e",
		["¿Te han hablado del Tren, verdad? ¡Es una auténtica maravilla! Lo encontrarás hacia el final del Distrito de los Enanos. Oh, y procura no sacar los brazos ni las pierdas del tren cuando esté en marcha."] = "98484e0cd95c72af21e16247f3eead70",
		["Ah, La Rosa Áurea... con sus cómodas camas y los baños calientes... con solo pensar en esa posada me entra... aauuhhh... Eres $gafortunado:afortunada; si vas hacia allá... la encontrarás en la parte oeste del Distrito de Mercaderes... suaves almohadas, cálidas mantas... aaauhhh..."] = "e84a11ab6b3896ecf97c8adfbc08636c",
		["Ahhh, buscas a Dungar Tragolargo. ¡Cuenta con uno de los grifos más rápidos de este lado de Khaz Modan! Lo encontrarás en la muralla del Distrito de Mercaderes."] = "a36856bf0646fdd5ce14e1bbdbeab7a2",
		["¿Que vas a crear tu hermandad? Entonces, ¡buena suerte!\n\nVe a ver a Aldwin Laughlin en el Centro de Viajeros de Ventormenta. Está en el Distrito de Mercaderes, que está justo al entrar desde el Valle de los Héroes."] = "dbd178f951b41e05c59af921ec3b7725",
		["No sé cómo lo hacen... esos buzones deben ser portales mágicos o algo así. ¡No paro de ver a gente amontonada alrededor del buzón que está junto al banco sacando espadas, escudos y armaduras de esa diminuta cosa!"] = "b4b551dc6175faa3e32ad05a88b10b09",
		["Si necesitas un alojamiento para tu mascota mientras estás entrenando a otra, deberías hablar con Jenova Petrescudo, en el Distrito de los Enanos."] = "b68ea919378ae726f910e862a386d16f",
		["El maestro Woo Ping domina casi todas las armas que conoce el hombre. Es especialmente mortal con sus técnicas de espada. Pasa mucho tiempo en el Arsenal de Weller, esperando nuevos cargamentos de armas. Lo encontrarás allí si necesitas entrenamiento."] = "ea46258d498568523f3fadf071cc9af0",
		["Bueno, bueno... ¿Ascendiendo en el mundo, eh? Estás buscando la Sala de los Campeones, y la encontrarás en la parte sureste del Casco Antiguo. Si eres un oficial, podrás entrar. Si no es así, tendrás que hablar con el oficial Areyn que está fuera. ¡Buena suerte!"] = "a0e2103ae01da9c6c1707056a504c6ae",
		["Ojalá pudiera irme contigo, $n. Vete al Castillo de Ventormenta. Encontrarás a Thelman Puñopizarra en la sala de audiencias del rey. Te ayudará a llegar hasta el Valle de Alterac."] = "5da822272073a4d726872184c3421ca6",
		["Es admirable lo que la Liga de Arathor está intentando hacer en la Cuenca de Arathi. El problema es que esas abominaciones de los no-muertos y sus amigos de la Horda están en medio. Dirígete al Castillo de Ventormenta. Lady Hoteshem te espera en la sala de audiencias del rey. Puede ayudarte a llegar a la Cuenca de Arathi."] = "adb9b1e902dc3d39490b7c0e4c0e67cd",
		["Los centinelas Ala de Plata necesitan toda la ayuda que puedan conseguir para luchar contra los escoltas Grito de Guerra. $n, vete al Castillo de Ventormenta y habla con Elfarran si quieres ayudarles."] = "a28ad28e180fb23f6b2f30a8926dd8d3",
		["El parque es el lugar al que tienes que dirigirte si buscas instructores druidas. A Theridan y a Maldryn los sueles encontrar junto a la Poza de la Luna, en el centro del distrito."] = "6ca4fdf838b083f58d40a21536adeaed",
		["¿Un cazador? Bien, entonces querrás hablar con Thorfin Petrescudo, en el Distrito de los Enanos. \n\n Oh, ¡y asegúrate de decirle que si vuelvo a pisar algún regalo de su mascota tendrá que instruir a los cazadores desde detrás de las barras de las Mazmorras!"] = "d9d6fc265ce7e558402d3ca53747dac5",
		["Buscas pistas sobre lo arcano, ¿verdad? Entonces no hay mejor lugar que el Sagrario del Mago, en el Barrio de los Magos."] = "0493aff58b480f500d524b265550d281",
		["Laurena es la suma sacerdotisa de Ventormenta. La encontrarás en la Catedral de la Luz, en la Plaza de la Catedral."] = "4a22a1b67aa8fe418d517ebb0e371796",
		["Bah, los pícaros no han hecho otra cosa que darnos más trabajo aquí en Ventormenta. Me gustaría poder sacar a Osborne y a Matías fuera del Casco Antiguo para meterlos directamente en las mazmorras."] = "6e24adae0babfe7f1e128960d09c55af",
		["¿Brujos, eh? Bien, no digas que te lo he dicho yo, pero he oído rumores de que esos tipos se reúnen en una taberna llamada El Cordero Degollado, en el Barrio de los Magos."] = "f05de425d7bd02752037b8477cf01b53",
		["¿Buscas instrucción? Podría instruirte mejor que cualquiera en Ventormenta, pero la guardia lo prohíbe. Creo que vas a tener que quedarte por aquí, pues uno de ellos anda por el cuartel o en la taberna El Cerdo Borracho en el Casco Viejo."] = "cd7fa3fdce25e94d80b36771810f1e93",
		["Escondida en el Barrio de los Magos hay una pequeña tienda llamada El Rincón del Alquimista. Cuando atravieses el Barrio de los Magos verás todo tipo de extrañas tiendas, pero si no te separas del borde exterior seguro que la encontrarás."] = "8651024fca6f7bd42a0336d52e7d69fc",
		["¿Quieres decir que no puedes oler el humo de las forjas de los enanos desde aquí? Bueno, si quieres aprender herrería estarás buscando a Therum Forjahonda. Está en el Distrito de los Enanos, justo al norte de la Plaza de la Catedral."] = "a3a18a74f32a8ebab3109103db8d0fd5",
		["Hay un gran cocinero que trabaja en la taberna El Cerdo Borracho del Casco Antiguo. He visto cómo maneja el cuchillo cuando cocina y, entre tú y yo, no creo que siempre haya sido un cocinero. Pero no me entiendas mal... si sigues queriendo instruirte, él es el mejor de la ciudad."] = "af66b0b5d2d42f34571240ac0c887807",
		["Ah, estás buscando a Lucan Cordell. Lleva una tienda en las afueras del Barrio de la Magia, de camino a las Mazmorras."] = "e3f9bcedb2188218c92b8b8fb1e8eb6a",
		["Eh, eso me recuerda que tengo que reparar mis botas cohete. Pero te daré un buen consejo, no mezcles las botas cohete con los grifos. \n\nOh, pero necesitas que te ayude con algunas señas... dirígete al Distrito de los Enanos, encontrarás a Lilliam Chispeje por la parte de atrás."] = "bb3fee63f3293484e591674a691d3c88",
		["No hay ningún lugar mejor para aprender primeros auxilios que bajo la atenta mirada de Shainar Fuller en la Catedral de la Luz. \n\nPara ir allí solo tienes que buscar los tejados amarillos o la altísima aguja de la Catedral, la podrás ver desde casi cualquier punto de la ciudad."] = "b1be3018807cc2da500145c8c2b10794",
		["¿El holgazán de Leland? Todo lo que hace es sentarse en los muelles de la parte exterior del Distrito de los Mercaderes y pasarse todo el día pescando. Tiene que ser realmente bueno porque no hace otra cosa. Si quieres aprender, ¿por qué no vas a hablar con él?"] = "2472ef40c4054390e47d26a2790dcef8",
		["No hay nada como la comunión con la naturaleza... al menos es lo que me dicen los elfos de la noche. Yo no soy de los que se pasan el día hablando con las flores y con los árboles, pero seguro que Tannysa podría ayudarte. Está en el Barrio de los Magos en el exterior de El Rincón del Alquimista."] = "42747362bb8e6d2164d7e79747248058",
		["¿Te interesa el cuero, eh? Creo que deberías hablar con Simon Peletero en el Casco Antiguo. Lleva una tienda llamada La Piel Protectora."] = "02b8fd48e20c73453938adc9f4995c2c",
		["Fueron los enanos los que enviaron un especialista en minería desde Forjaz para enseñarnos a excavar. ¿Tan difícil puede ser coger un pico y dar golpes a una piedra? Pero bueno, como está aquí seguramente deberías ir a hablar con él. Su nombre es Gelman y vive en el Distrito de los Enanos."] = "64070f95813e914bdca6f15e390c919e",
		["Podría atravesar a un orco y cortar un trol en pedazos, ¿sabes? Hasta podría tallar mis iniciales en las costillas de un ogro, pero soy incapaz de desollar a un animal. ¡Imagínate! \n\nBueno, si tú tienes suficiente estómago ve a ver a Maris Granger en La Piel Protectora del Casco Antiguo."] = "c7ce82c152a63bc669f1d309ce17f9bd",
		["¿Un sastre? Bien, si te quedas por aquí un rato seguramente oirás hablar de Georgio Bolero. Ha estado marcando la moda durante meses. Si quieres instruirte con él podrás encontrarlo en el borde exterior del Barrio de los Magos."] = "9cba4dc5407b5b21f860b325ab149a86",
		["¿Hacia dónde quieres dirigirte?"] = "2402ec9453525b4ec16e1180457c7cfb",
		["Está en el Distrito de Mercaderes. Siguiendo recto desde la entrada de Ventormenta."] = "568c01f3e19d99d5f41ea3aac2056ebe",
		["El Banco de Ventormenta está ubicado en el Distrito de Mercaderes, exactamente al noroeste de las puertas de la ciudad. Mira, te lo muestro en el mapa."] = "8fedf8298f3edb222d5b5f4355c58675",
		["Tu estómago no aguanta un viaje en grifo, ¿eh? Has tenido suerte, ¿preguntas si hay otra opción para no tener que separar los pies del suelo? Más o menos. Se trata del transporte de los gnomos, el Tren Subterráneo. Está oportunamente situado en la parte trasera del Distrito de los Enanos."] = "b8a17986e4d6330f2e74f8f8a53c0d86",
		["Hay muchos establecimientos para tomar un trago en Ventormenta, pero solo en uno puedes pasar la noche. Dirígete a La Rosa Áurea del Distrito de Mercaderes. He oído que el precio de una habitación es bastante razonable, y las sábanas están limpias."] = "44af32f368e03c09b89fe9f87be3875e",
		["Encontrarás al maestro de grifos en la muralla del noreste, con vista al Valle de los Héroes."] = "f5c1db946eb2f4fba13e922275d9fb95",
		["Encontrarás a Aldwin Laughlin en el Centro de Viajeros de Ventormenta, en el Distrito de Mercaderes."] = "53cfbdba892d116c2e03388c9fd6d5d0",
		["Hay un buzón estratégicamente situado entre el banco de Ventormenta y la posada La Rosa Áurea en el Distrito de Mercaderes."] = "bb63ff9d75c7726f1d06e21fe2021b8b",
		["Tienes que buscar a Jenova Petrescudo, está en el Distrito de los Enanos. Se encarga de cuidar a las mascotas de los cazadores mientras su padre las entrena."] = "9654c77653b91d446f531295982fbec7",
		["La fortaleza de Woo Ping es realmente increíble. Cuando le veo practicar sus técnicas durante horas acabo sintiendo lástima por el muñeco con el que practica. No imagino a nadie más apropiado para instruirte en el combate con armas."] = "312810e5deb14cd60aa19428f7f51227",
		["¿Así que ahora, de pronto, eres $gun 'Defensor de la Alianza':una 'Defensora de la Alianza';? Bueno, supongo que querrás ir a la Sala de los Campeones. Está en el Casco Antiguo, pero no te dejarán pasar a menos que seas un oficial, así que quizás tengas que conformarte con hablar con el oficial Areyn que está fuera. Vete de aquí."] = "33278f8101e800c93fc3d2385cfed699",
		["¿Qué campo de batalla te interesa?"] = "481f209702cc74fc87fe4569d25b276b",
		["¿Qué tipo de instructor estás buscando?"] = "7e357056bac5b73342ac2bee0458e300",
		["¿Qué tipo de instructor de profesiones estás buscando?"] = "ce83ae92effc9c6509cef60c5f919389",
		["Tienes que hablar con Thelman Puñopizarra. Le podrás encontrar en presencia del rey, en el Castillo de Ventormenta."] = "bcfcce27aafd9e54ef3d2fcdb27f4139",
		["Encontrarás a Lady Hoteshem en la sala de audiencias del rey. Puede ayudarte a llegar a la Cuenca de Arathi, donde la Liga de Arathor necesita ayuda contra los Rapiñadores."] = "9ff1ef7f7918452a7571c3f770ab4e14",
		["Además, el Bastión Ala de Plata necesita tu ayuda. Habla con Elfarran en la sala de audiencias del rey en el Castillo de Ventormenta."] = "ab67b49961ce98725cccb8a6b0e8e7ef",
		["Bueno, puedes encontrar a Theridan o a Maldryn en la poza de la Luna que está en el parque. Ve hacia la zona oeste de Ventormenta, al norte del Distrito de Magos, pero al oeste de la Plaza de la Catedral."] = "2c1e9110dff51f5d1d491b13523c5989",
		["Thorfin Petrescudo vino desde Forjaz para transmitirnos sus conocimientos de caza. Si no te importa respirar el aire contaminado del Distrito de los Enanos, entonces lo encontrarás en su casa, situada en la zona noreste del distrito."] = "8c8ac67be8a32d83d11e1119cbe8b9f8",
		["Los magos se reúnen en el Sagrario del Mago, en el Barrio de los Magos. Vaya torre la que tienen allí. Hace que nuestros cuarteles parezcan casuchas de campesinos."] = "338c8fab07f57033e48217d5973c15df",
		["Si quieres convertirte en un poderoso paladín, no encontrarás mejor maestro que Lord Grisillo Quiebrasombras. Lo encontrarás en la Catedral de la Luz, en la Plaza de la Catedral."] = "2d22a7afddcc8d88b9c1353ae28daf09",
		["La Catedral de la Luz, en la Plaza de la Catedral, es el hogar de los sacerdotes de Ventormenta. Allí encontrarás a la suma sacerdotisa Laurena."] = "bb897a746e8a30c2b211e9076b6a286d",
		["Entonces querrás hablar con Osborne. No encontrarás mejor maestro de las artes del sigilo en todo Ventormenta. Búscalo en el Casco Antiguo."] = "5079ccedcf83df1e6554116dbaa337bd",
		["¿Qué? No conozco instructores brujos en Ventormenta. \n\nNo obstante... dicen que se han celebrado actos demoníacos en El Cordero Degollado, en el Barrio de los Magos. Supongo que podrías mirar allí."] = "f6a52f523eecff532c9530eae7d0e89a",
		["Normalmente los guerreros se encuentran en la taberna El Cerdo Borracho o en el cuartel del Casco Antiguo. Pero créeme, lo mejor será buscar en la taberna."] = "9434f3b21efa2de084243d600d530ff5",
		["Sin necesitas instrucción en alquimia, hay un solo lugar en Ventormenta al que tienes que ir... El Rincón del Alquimista. Lo encontrarás en el Barrio de los Magos, en la calle de tiendas que está situada hacia las afueras."] = "7034523efe4bfc8203b790a1d127dca2",
		["Therum Forjahonda es el enano al que buscas. Uno de los mejores herreros de por aquí. Lo encontrarás en el corazón del Distrito de los Enanos."] = "a4956fb4f50c46eaea4f68dd50ceb194",
		["Si lo que deseas es convertirte en $gun gran cocinero:una gran cocinera;, ve a la taberna El Cerdo Borracho, situada en el Casco Antiguo, y habla con Stephen Lomocenteno. Ese hombre prepara unas costillas como nadie en el mundo.\n\nHombre, ya me ha entrado hambre y ahora daría cualquier cosas por comerme sus famosas costillas. Pero ¡no cuentes con que te dará la receta!"] = "dbe19e29f297c8e1fb35a95e50f89466",
		["Lucan Cordell tiene una pequeña tienda junto al canal, cerca de las mazmorras. Seguro que te podrá enseñar las artes del encantamiento."] = "91e3f367dbb0e83b362a5880d1271dc4",
		["El instructor en ingeniería que vive en Ventormenta es un gnomo ingenioso al que todos conocen como Lilliam Chispeje. Lo encontrarás al final del Distrito de los Enanos."] = "05e90b70ee82c6ab15e68fec597454c2",
		["La Catedral de la Luz es el centro de todas las prácticas curativas de Ventormenta. Ahí encontrarás a Shaina Fuller para que te enseñe su oficio."] = "fd43bf9ef9a4ea5b42ea21a6017c205b",
		["No hay nada como pasar un día pescando en el Lago de Cristal. Arnold Leland es quien me enseñó. Suele estar en el muelle del Distrito del Canal, pescando durante todo el día. \n\nAh, y no le creas ninguna de las historias que cuenta sobre monstruos en los canales."] = "852f678dbc06d3601bdf168e7032735a",
		["A Tannysa la encontrarás en la entrada de El Rincón del Alquimista, en el Barrio de los Magos."] = "356b1700581f2c27333ab266a26bb077",
		["¿Quieres aprender el oficio de la peletería? Simon Peletero podría enseñártelo. Lo encontrarás en el Casco Antiguo en La Piel Protectora."] = "52ef93000b10574ffb40f6f451597e26",
		["Gelman Manopétrea es la persona indicada. Creo que tiene una casa en el Distrito de los Enanos, pero no recuerdo exactamente dónde. Yo lo buscaría por allí."] = "8f8f48c440d58b1a783b868dd9222e74",
		["Ahora bien, si lo que quieres es aprender el oficio del desuello, entonces deberás dirigirte al Casco Antiguo y entrar en La Piel Protectora."] = "6f55eb7e6eebe144bc957790dae41464",
		["Uno de los empleados de los Textiles de Duncan, Georgio Bolero, es uno de los mejores sastres de Ventormenta. Busca la tienda en el Barrio de los magos."] = "8706ad14fe81bd7bfe9d6986ff68ed63",
	},
	[197] = {
		["¡Eh, $gciudadano:ciudadana;! Pareces fuerte. Nosotros, los guardias, no tenemos una presencia demasiado densa ahí fuera, podría necesitar tu ayuda..."] = "2343fa9b01b2ca00b5bc7a390ac07935",
	},
	[198] = {
		["Buenas, mago. ¿Quieres que te enseñe más secretos del mundo de la magia?"] = "3ddc082eac22c52bb34743331a694904",
		["Bien hallado, $c. Mi consejo para ti es este: cuando viajes por el mundo sé precavido con la magia porque puede acabar con el profano."] = "54074b0b08d3a499512ae6fba95f3115",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	[223] = {
		["Cuando conseguí arrastrarme fuera de la tumba, creí que mi familia me recibiría con los brazos abiertos. Pero, al contrario, me echaron de la aldea, gritando en un idioma que ya no podía comprender."] = "94095eb43627763b471b3b24bdf02a82",
	},
	[233] = {
		["Son tiempos difíciles, ¿verdad, $n? Mires a donde mires, siempre hay alguien que necesita ayuda, y mi mujer y yo no somos ninguna excepción."] = "d9ee732b87b8a6f2898035304c1bf290",
	},
	[277] = {
		["¿Solo estás examinando mis mercancías o hay algo específico que quieras encontrar hoy?"] = "a86de99ac7614f683ab7eab24b0a0b93",
		["Los mejores precios en todo Ventormenta, $gamigo:amiga;, no encontrarás mejores precios. Y bien, ¿en qué puedo ayudarte?"] = "0a50227fd4a79a221c5e74147031f06e",
	},
	[295] = {
		["Te doy la bienvenida a mi taberna, $gfatigado viajero:fatigada viajera;. ¿En qué puedo ayudarte?"] = "e3e01e02de026cbe5e2560a468bbdebb",
		["\"¿Qué puedes hacer en una posada?$B$BBueno, cuando te quedas en una posada, descansas cómodamente. Por esta razón, estarás “más descansado” en mucho menos tiempo que si lo haces en el bosque. Cuando descansas bien, aprendes más de la experiencia.$B$BAsimismo, puedes pedirle al posadero que te consiga una piedra de hogar para luego usarla con el fin de regresar rápidamente a la posada”."] = "8fc274a3d994a2459bdce3fd3dc98705",
		["Yo no, pero muchos por ahí sí buscan amor. ¡Deberías comprarme pruebas de amor, echarte un poco de colonia o perfume y pasar a su lado!"] = "137f53b5268a04b1b5bdb21820557b14",
		["Si te echas colonia o perfume, podrás ver quién está buscando amor. Esos aceptarán pruebas de amor... y te entregarán un regalo a cambio.$B$BPero recuerda: para darle a alguien una prueba de amor, ¡deberás oler bien! A los hombres les gusta el perfume mientras que las mujeres prefieren el olor de la colonia."] = "206f059d0c629c5d37a5efc62769a4a3",
		["Las pruebas de amor son mensajes de cariño que puedes entregar a la gente de la ciudad que esté buscando amor. Esas personas te recompensarán con un regalo de adoración.$B$BSi ya tienes a alguien que te adore, entonces te entregarán un regalo de amistad."] = "d268a407b36e89a7c70ab981fb46abd7",
		["Cuando entregues pruebas de amor a los habitantes de la ciudad, recibirás diferentes regalos a cambio. Algunos podrás guardarlos y utilizarlos, y otros podrás juntarlos y dárselos a tu $ghéroe favorito:heroína favorita;! Visita a Kwee Q. Mercachifle y entrégaselos.$B$BEncontrarás a Kwee cerca de Bolvar, Magni o Tyrande."] = "fa856e726cbf60331453148913410f70",
		["Cuando entregues pruebas de amor a los habitantes de la ciudad, recibirás diferentes regalos a cambio. Algunos podrás guardarlos y utilizarlos, ¡mientras que otros podrás juntarlos y dárselos a tu $ghéroe favorito:heroína favorita;! Visita a Kwee Q. Mercachifle y entrégaselos.$B$BEncontrarás a Kwee cerca de Cairne, Sylvanas o Thrall."] = "616aaf989a9683312fafbb75a48fe26b",
	},
	[328] = {
		["Buenas, mago. ¿Quieres que te enseñe más secretos del mundo de la magia?"] = "3ddc082eac22c52bb34743331a694904",
		["Bien hallado, $c. Mi consejo para ti es este: cuando viajes por el mundo sé precavido con la magia porque puede acabar con el profano."] = "54074b0b08d3a499512ae6fba95f3115",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	[331] = {
		["Buenas, mago. ¿Quieres que te enseñe más secretos del mundo de la magia?"] = "3ddc082eac22c52bb34743331a694904",
		["Bien hallado, $c. Mi consejo para ti es este: cuando viajes por el mundo sé precavido con la magia porque puede acabar con el profano."] = "54074b0b08d3a499512ae6fba95f3115",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "f6708bdc5d32f47f0eaf4fce7cf2764c",
	},
	[332] = {
		["Te doy la bienvenida al puesto de mando de IS:7, $N."] = "f02518f56be86de855c4a5c585841f34",
	},
	[347] = {
		["Lo siento, $c, pero necesitas más experiencia para sobrevivir en el Valle de Alterac."] = "b83ab9c1a9dd85b93121a8a221e21094",
		["¡Hay que destruir a la Guardia de Pico Tormenta! ¿Estás $glisto:lista; para el Valle de Alterac, $c?"] = "81ed3ff7e3aa4663fea43677ac077dd8",
	},
	[352] = {
		["Estas grandes bestias conocen caminos que jamás encontrarás yendo a pie. Pueden llevarte a gran velocidad y tal vez también te enseñen cosas nuevas al mismo tiempo."] = "483ae8ef81d9a1fa5470403f505b2d87",
		["¿Adónde quieres ir, $gmuchacho:muchacha;? Por unas cuantas monedas, mis grifos pueden llevarte incluso más rápido que el más veloz de los caballos."] = "6b05ee484d45803ee175e05a07d644f4",
	},
	[375] = {
		["Espero que la Luz esté contigo, $n. ¿Puedo ayudarte en algo?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["No des la espalda a la Luz, $c, puede ser lo único que te salve algún día."] = "120875f188ac12780f811009b51a783b",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	[376] = {
		["Espero que la Luz esté contigo, $n. ¿Puedo ayudarte en algo?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["No des la espalda a la Luz, $c, puede ser lo único que te salve algún día."] = "120875f188ac12780f811009b51a783b",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	[377] = {
		["Espero que la Luz esté contigo, $n. ¿Puedo ayudarte en algo?"] = "aebf3948f2b6eeebadd9d114b8e08bba",
		["No des la espalda a la Luz, $c, puede ser lo único que te salve algún día."] = "120875f188ac12780f811009b51a783b",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	[384] = {
		["¡Mis años de experiencia como criador y todos mis cuidados me otorgan el privilegio de mostrarte estos caballos! Por favor, tómate tu tiempo para examinarlos. Un caballo te acompañará durante años, $gamigo:amiga;. ¡Hazte valer y adquiere hoy mismo tu montura!"] = "0016d0ff7c43ada7e4f367d5b24e9b81",
		["Lo siento, pero no estoy dispuesto a vender caballos a alguien a quien el Reino de Ventormenta no considere exaltado. Estos corceles son los mejores que se pueden encontrar y, ciertamente, no queremos que caigan en manos enemigas.$B$BNo estoy diciendo que seas $gun enemigo:una enemiga;, no... Solo tienes que ganarte la confianza de Ventormenta y después podremos hacer negocios."] = "33c0e9087e12555f8dc52cc2a68cccb1",
	},
	[459] = {
		["La oscuridad no te abraza, $c. ¡Déjate de chácharas y sal de mi vista! ¡Lárgate!"] = "2aabd37566ced1f9550e86910bb3baf8",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	[460] = {
		["El poder arcano solo corrompe a los débiles. Sigue con tu instrucción, o podrías acabar encontrando un destino similar."] = "073492d1b775dad17b73e4495accc8b7",
		["Me temo que tu grado de oscuridad no es suficiente como para que me moleste en seguir hablando contigo. Vete de aquí, por favor."] = "8045db4a1a25656b86eb87b955fbe642",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "a9083a5c3e3237e00bd856dcc0fd400d",
	},
	[461] = {
		["El poder arcano solo corrompe a los débiles. Sigue con tu instrucción, o podrías acabar encontrando un destino similar."] = "c381816693d5bcf8cf6644c3ad7a0dea",
		["La oscuridad no te abraza, $c. ¡Déjate de chácharas y sal de mi vista! ¡Lárgate!"] = "2aabd37566ced1f9550e86910bb3baf8",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "768f0928588ebe52253715a9f6b21ad7",
	},
	[483] = {
		["¿Solo estás examinando mis mercancías o hay algo específico que quieras encontrar hoy?"] = "b27e9e38daaae8b0ac9e5d7775fe5a70",
		["Los mejores precios en todo Ventormenta, $gamigo:amiga;, no encontrarás mejores precios. Y bien, ¿en qué puedo ayudarte?"] = "930e45368ed7dcac8e799df8fa5bc730",
	},
	[491] = {
		["Intento mantener la Colina del Centinela abastecida, y no es fácil con toda esta acción."] = "f25d9eb86b1a32dfb1649beab901ef4c",
	},
	[514] = {
		["Lo siento, estoy bastante ocupado ahora mismo haciendo herraduras para Verner Bonmete de la Comarca del Lago."] = "80c8a703f2783e988393cdc3f26954dd",
	},
	[523] = {
		["¿Qué estás haciendo? ¡Si quieres ir allí rápidamente, no sigas mirando!"] = "a8c3fee28c1869e9b77707e11b8cd0a2",
	},
	[543] = {
		["¿Has venido en busca de instrucción para poder pasársela a tus mascotas?"] = "89218c24a0eff1fa5c10022467769ef7",
		["Oh, solo ayudo a los cazadores y sus mascotas."] = "4c9a93178a8bd81be46f856336284914",
	},
	[658] = {
		["Ah, ¡qué aspecto tan robusto! Quizás puedas ayudarme con algunas cosas. Por aquí no es necesaria mucha ayuda, excepto para los aprendices verdes, y esos tienen otras cosas por las que preocuparse."] = "5fc097432cec6da6622815d859a41a7a",
	},
	[716] = {
		["Al maestro Nesingwary le espera una gran cacería. Encuentro mucho más relajante ayudarle a prepararse para un día en la jungla, que para el combate. Aunque echo de menos algunos de esos momentos gloriosos en el campo de batalla."] = "e3a348a35882a9d1e3d9c86ff56b6bbe",
	},
	[727] = {
		["Las Arcas de Forjaz son el banco más cercano que encontrarás por estos lares."] = "83965dbeffe98cceda0d3e3dbf0734c2",
		["El maestro de grifos más cercano está en Forjaz, junto a La Gran Fundición. Tendrás que dirigirte a Forjaz si quieres viajar en grifo."] = "c32efb4b50768d9afd75e50dc0393a88",
		["Si quieres echarle mano a los papeles para crear una hermandad tendrás que ir a Forjaz y visitar el Centro de Viajeros."] = "395a422b3eb1d579d18416f0b5ef4bff",
		["Oooh, ¿una posada? No hay ninguna como la Destilería Cebatruenos. Descansa si lo necesitas y tómate una cerveza o dos cuando estés ahí."] = "e66a69d239e7c3f1206d7f638c44bec1",
		["Shelby Petrepiedra da alojamiento a muchas de las mascotas de los cazadores locales. Está en la Destilería Cebatruenos. Vete a hablar con ella si quieres que te cuide alguna mascota."] = "5011b7376cf9fbdf9a91842132fba2e6",
		["Si me preguntas, creo que Grif pasa demasiado tiempo con los animales. Aun así, nadie conoce tan bien como él la senda del cazador. Búscale a las puertas de la herrería de Kharanos."] = "5d54f11c82628de5397e4af70d935d39",
		["¿Seguro que no quieres aprender a ser un guerrero? Bueno, tú decides cómo jugarte el pellejo en el campo de batalla. Si de verdad quieres aprender a menear los dedos, lo mejor será que hables con Magis Chispamanto, en la Destilería Cebatruenos."] = "3361a9560236765dd4f9f954267bed44",
		["¿Necesitas instrucción? Bien, Azar Martillopujante siempre está dispuesto a enseñar a los jóvenes paladines una cosa o dos. ¿Por qué no vas a verle a la Destilería Cebatruenos?"] = "63af3d038f4096f6bba167a9b297ef08",
		["Sin duda encontrarás a Maxan Anvol tomando un trago en la Destilería Cebatruenos. Por qué no te vas a tomar una pinta y a ver si te enseña algo nuevo."] = "f9ef4e04eea4de713fc61313fd8a4c8e",
		["¿Buscas a Hogral? Bien, ¿miraste en la taberna? ¡Oh! ¡Si estás buscando a un pícaro, y además enano, deberías comenzar buscando en la posada! ¡Ve a echar un vistazo!"] = "d218e9d1194ff62a08601af71245f9b8",
		["Ese tipo de magia solo trae malas noticias, hazme caso. No sé por qué han permitido que Grimrizz se establezca justo a la puerta de la Destilería Cebatruenos. ¡Más te vale no acercarte a él!"] = "f1180972db6665288081c1cfc7b5f408",
		["Ese Granis Hachaveloz podría beber tanto como un pez y su hacha seguiría siendo la más certera. Pero si quieres que te instruya lo mejor será que lo pilles cuando puedas entender lo que dice."] = "ee5ecc14e2bf49a6990e74cae4288e7b",
		["He oído que hay una tienda de gnomos en Forjaz especializada en alquimia. Deberías ir a echar un vistazo."] = "e59e7a5d5007c14bc99785f8ce315a5c",
		["Cuando llegues a Kharanos probablemente oigas a Tognus golpeando el yunque. Aunque, si tienes los oídos llenos de cera, siempre puedes echar un vistazo en la forja."] = "9f64ea1b3225a2261a71922332f8c889",
		["Gremlock no siempre tiene mucha suerte cuando cocina, pero tiene algunas recetas muy sabrosas y que merece la pena aprender. Ve a charlar con él en la Destilería Cebatruenos y mira qué puede enseñarte."] = "812ca9ddb549b5088d51719a6d51434b",
		["Deberías echar un vistazo en Forjaz si tienes la idea de convertirte en $gencantador:hechicera;. Creo que vi una tienda junto al maestro de grifos la última vez que estuve allí."] = "e56f9fe4500923af12e19f791a883d14",
		["Con todos los tornillos que ha ajustado Bronk, creo que alguna vez ha tenido que utilizar alguno de los suyos... ya me comprendes. Aun así sigue teniendo buena cabeza para hacer los inventos más increíbles. Deberías hacerle una visita en el Almacén de Brasacerada."] = "d505dd7c90c149052d96dc5021198f21",
		["El bueno de Thamner me vendó el otro día, cuando me las vi con un asqueroso trogg. ¡Estoy como nuevo! Seguro que a Thamner le gustaría enseñarte a hacer un buen vendaje."] = "93839b8ccc68c7af9e06e65b17c1fd90",
		["Por aquí solo se puede pescar en unos pocos lugares. Paxton los conoce y seguramente también conozca algún otro del que no diga nada. ¿Por qué no vas a verlo al Lago Glacial y ves qué te cuenta?"] = "8bbfc8f6de8eca0089d8559839569436",
		["No, no hay nadie que pueda enseñarte botánica por aquí. Creo que tendrás más suerte en Forjaz."] = "5aaf2f083eef745315ab1a2dc692fcb0",
		["Para encontrar instructores de peletería lo mejor será que te dirijas a Forjaz. Si mi memoria funciona, hay una tienda en La Gran Fundición, allí encontrarás todo lo que necesitas."] = "712130efaf95afb9ccb5f2a5c069c0fc",
		["¿Un minero? ¡Lo único que tienes que preguntar es dónde $gmuchacho:muchacha;! Yarr es el hombre a quien buscas, creo que pondrás encontrarlo en el Almacén de Brasacerada."] = "4ef02a6cde5565b37e151274512c0641",
		["Normalmente los desolladores llevan sus pellejos a Forjaz para curarlos. ¿Por qué no vas allí para ver si encuentras a uno que quiera instruirte?"] = "12bf423a5f31db52e9d292ceb06ece6b",
		["Bien, no vas a tener mucha suerte si buscas por aquí a un sastre. Pero Forjaz es el hogar de algunos sastres muy dotados. ¿Por qué no vas y preguntas a uno de los guardias de la ciudad?"] = "720fafcfb6472426d4149a74769fda89",
		["¿Adónde deseas ir?"] = "411e9efc17c0fa67fa3a65ddbceb693f",
		["El banco más cercano son Las Arcas de Forjaz, $gmuchacho:muchacha;."] = "501c83ee292da27782fae1e60bf7c3f3",
		["No encontrarás ningún maestro de grifos por Dun Morogh, $gmuchacho:muchacha;. Tendrás que ir hasta Forjaz si quieres ir en grifo a alguna parte."] = "f3c8a5a8b088f61349bd467d2e1e02b1",
		["Todos esos oficiales residen en Forjaz. Tendrás que acudir al Centro de Viajeros de Forjaz, allí obtendrás los documentos necesarios para fundar una hermandad."] = "f9fd222716447c9fab43d7fdd2bdcab4",
		["Los Cebatruenos tienen una agradable posada en Kharanos que lleva su nombre. Entra a tomar una pinta y a descansar un poco."] = "0ee12bb81d2947b566609b7ba822b401",
		["Bueno, bueno $gmuchacho:muchacha;, puedes encontrar a Shelby Petrepiedra justo fuera de la Destilería Cebatruenos en Kharanos. Cuidará bien de tus mascotas."] = "bee5611eb524aaf54dfb7c803d87d4c9",
		["¿Qué tipo de instructor de clases estás buscando?"] = "dcadd0f33e63218ef70a191c145117f6",
		["¿Qué tipo de instructor de profesiones estás buscando?"] = "cf38911600ac02c04cb72aafa6596e66",
		["Solo puedo darte el nombre de un cazador por estos alrededores, Grif Corazón Salvaje. Lo encontrarás en la misma puerta de la herrería de Kharanos."] = "3043df25383951a157419bf109bd7229",
		["Hay un mago en la Destilería Cebatruenos, seguro que él podrá enseñarte algunos hechizos nuevos. Creo que su nombre es Magis Chispamanto."] = "cfa572bac748ea1fa7e7c25dc2a4ae04",
		["Oh... ¿un paladín? Bien $gmuchacho:muchacha;, ¡estás de suerte! Azar Martillopujante ha vuelto de su entrenamiento y se encuentra en la Destilería Cebatruenos de Kharanos."] = "9d8f2dd4c4db277f02b3c5d5f15c9354",
		["Oh, ¿un sacerdote? Si necesitas instrucción podrás encontrar al bueno de Maxan tomando un trago en la Destilería Cebatruenos."] = "9a7b6a50e57d38d1acb4f3bff531e0f2",
		["Veamos, parece que los dos estamos buscando a Hogral Bakkan. Es un enano de pura cepa así que tarde o temprano estará yendo a la Destilería Cebatruenos para tomar una cerveza. Puede que incluso ya esté ahí."] = "1f4384179f7f2eff7cf1e505f549b91e",
		["Brujos... No me interesan mucho esos tipos. Como ese Grimrizz que tiene una tienda junto a la Destilería Cebatruenos. ¡Seguro que la cerveza acabará perdiendo todo el gas por su culpa! Brujos... ¡bah!"] = "60bf6744b34a4b35ea7e3f938b4de2fd",
		["¡Aj! ¡Por fin algo interesante! Seguro que Granis Hachaveloz podrá enseñarte algo sobre el manejo del acero. Lo encontrarás en la Destilería Cebatruenos de Kharanos."] = "0fd2049ea24b3dbd43761a96e891bd61",
		["No, no hay ningún alquimista en Dun Morogh. Lo mejor será que vayas a buscarlos a Forjaz... prueba con los gnomos de Ciudad Manitas."] = "f7cf19aeccddff42a9a0b22c505718cc",
		["¡Aj! Merece la pena tener esas habilidades. Tognus golpea el yunque con una furia que no se ve muy a menudo. ¿Por qué no vas a hablar con él y ves qué puede enseñarte?"] = "5240f70aad5a8e58147ce8fae9c1ec57",
		["Una cerveza Cebatruenos y algo de la cocina de Gremlock son los ingredientes de la comida perfecta. Deberías ir a verle si quieres convertirte en $gcocinero:cocinera;."] = "d280277830161709ce905baf4cb22615",
		["No conozco a ningún encantador aquí en Dun Morogh. Vas a tener que visitar Forjaz si deseas aprender la profesión de encantador."] = "ccffed48b48def2c22f1c44f31434020",
		["Deberías buscar a Bronk en el Almacén de Brasacerada. Cuando no está jugueteando con alguno de sus inventos suele estar charlando con los pilotos sobre sus tanques de vapor."] = "f4fbd7429c935511c5657b11b95d1303",
		["Los primeros auxilios pueden no ser nada comparados con la curación de un sacerdote, pero son útiles cuando se está en apuros. Te recomiendo hablar con Thamner en la Destilería Cebatruenos y aprender con él todo lo que puedas."] = "a88b941bc8e164b364a0b5d642a579b5",
		["Por aquí no hay mucha pesca, pero lo poco que hay es para Paxton. Puedes encontrarle pescando en el Lago Glacial."] = "467b47eb9a3d4006f250fad9ecb18eb0",
		["Es fascinante ver cómo hay florecillas que resisten el frío de Dun Morogh... pero no encontrarás por aquí a ningún herborista. Tendrás que ir a Forjaz para instruirte en esa profesión."] = "3fd9a5ca3019eefa0d287e45aeacd7da",
		["Si quieres aprender peletería tendrás que viajar a Forjaz. He oído que hay una tienda junto a La Gran Fundición, allí podrás aprender la profesión."] = "5ca39ccf61fd158a1d527dc435d98222",
		["¡Ja! ¿No pensarías que ibas a encontrar una ciudad sin su minero, eh? Podrás encontrar a Yarr en el Almacén de Brasacerada, a las afueras de Kharanos."] = "1c9825e778eedca69936cc9dcbf549ef",
		["No encontrarás desolladores en Dun Morogh $gmuchacho:muchacha;, pero si necesitas instrucción seguro que podrás encontrarlos en Forjaz."] = "6a6954aa23ff423b51b954fe09b144a8",
		["Ah, Petrocejas no se aleja mucho de Forjaz estos días, así que si quieres aprender la costura, lo mejor será que vayas allí a buscarlo."] = "63ec46e6d95ea9bc754d4ccb65dd8202",
	},
	[738] = {
		["Es un lugar peligroso, $n. Ten cuidado por aquí."] = "a765bd81d4444d7fa3d03cdef9f00bd6",
	},
	[836] = {
		["¡He vendido las mejores prendas de género y cuero a este lado del valle!"] = "0f7736dc9f16d7152dca3f99e5a42807",
	},
	[837] = {
		["Que la Luz te proteja, $c."] = "852369f0d2fbc11e555e75fe5a433853",
		["Espero que la Luz esté contigo, $n. ¿Puedo hacer algo por ti?"] = "238a7cdf16a7d258e1b3789d98c5e7fb",
		["He tenido que realizar una rigurosa reconversión con muchos estudiantes de todo lo que habían aprendido, para poder enseñarles desde cero. El servicio que ofrezco aumenta de dificultad cada vez que se hace. Por esa razón, también aumenta el precio de cada nueva instrucción. ¿Quieres que elimine todos los talentos que has aprendido?"] = "31ab172e1a375db1c9157d594eb608d9",
	},
	[857] = {
		["La Cuenca de Arathi fue nuestro hogar, ¡y volverá a serlo con tu ayuda! ¿Nos ayudarás, $c?"] = "72c6e36686e172b92adf3e89a32b9bdf",
	},
	[895] = {
		["¿Qué puedo hacer por ti?"] = "ff4c1db50d39977890db3fe889ea21ae",
