	},
	[1304] = {
		["Yo solo vendo equipamiento arcano de la mayor calidad, fabricado por los artesanos y magos de Ventormenta."] = "2e4eca05cb76135045a9a7c0e66e45af",
		["Desde la caída de Dalaran y la destrucción de Quel'Thalas, este tipo de mercancías han sido difíciles de conseguir. Pero Lucan Cordell y alguno de nuestros otros comerciantes han realizado un buen trabajo al asignar mercancía de calidad a nuestros pedidos."] = "52ce57327118edf04bd3864c3342a693",
	},
	[1305] = {
		["Sigue mi consejo, no te sientes cerca de la oscuridad."] = "f74e7d5a245870415207560edfabf06d",
	},
