	[1311] = {
		["Te doy la bienvenida a El Ermitaño Azul, donde los adeptos a la magia se reúnen para soltar todo el vapor. No lo digo literalmente, claro. ¿Qué puedo hacer por ti, $gseñor:señora;?"] = "386f37176e6f7b06d34487928a573d23",
	},
