	},
	[3044] = {
		["¿Sí, $c?"] = "901d3b1160b38eacb61be277a1eab438",
		["¿Qué puede hacer por ti este insignificante siervo, $N? ¿Instrucción quizá?"] = "ca5ae8d63433bb1a991ae3a7d4a633fc",
		["¡Ah1 Tú eres quien ha encontrado la carta. Gracias por... las noticias, supongo, de mi familia. Puedes comer y beber de todo lo que hay."] = "c5b7759f0cefd29b1a309325dd586e97",
