	},
	[5118] = {
		["Lo siento, $c, pero necesitas más experiencia para sobrevivir en el Valle de Alterac."] = "f78c3c41a85a94fe125292149c2763de",
		["Y bien $gmuchacho: muchacha;, ¿$glisto:lista; para dirigirte al Valle de Alterac y darle a la Horda lo que está pidiendo a gritos?"] = "8b3c666dc6e4c0c98f9d6747a2aea0f8",
	},
	[5119] = {
		["¿Has traído tus libros de texto? ¿Puedo verlos contigo?"] = "e83e527b69146bb42674faef76761b94",
		["Vigila tus pasos aquí, $gchico:chica;. El maestro lo ve todo..."] = "17086fed84c5d89d563d8bdbaa21ee46",
		["¿Terminaste las tareas de ayer? ¡Si es así, siéntate a mi lado!"] = "f56e3e539d77c3bded51cb91595974e9",
		["¿Has olvidado tu uniforme de alumno? ¿Crees que la moda es más importante que la dominación de la Plaga?"] = "b1d9467fbe4dea13716545c2bf6c302f",
		["¡Silencio! ¡No puedo permitirme perder ni una sola de sus palabras!"] = "db9ed76ac5a5a639587d8f27fe9a6ec3",
		["¡Debemos centrarnos si queremos que desove nuestro Vuelo!"] = "320a21f122e733d1cb4deb8239b5a553",
		["Dedica menos tiempo a hablar y más a escuchar."] = "3cdaa01e5d3f9b1bf933f46723fe25d1",
		["¡Silencio! ¿No puedes ver que está hablando el maestro?"] = "54e82db9c1117db8533f92adc4933717",
	},
	[5127] = {
		["¡Mucho que hacer! No he estado tan ocupado desde que mi primo, accidentalmente, vaporizase todas las telas y el cuero de Gnomeregan. ¡Cielos, sí que todo estuvo húmedo durante un tiempo! Ah, $n, esos eran buenos días..."] = "844d2fb5a4d4d41fdd8a5e1cfc1061ab",
		["No, me temo que no puedo ayudarte. ¡Tu habilidad me aventaja! Si quieres aprender más, ve a ver al elfo de la noche Telonis en el Bancal del Artesano de Darnassus. ¡Es increíble!"] = "db9fa2c2d699dd1ac20a87ea78997fd7",
		["¡Por mis ancestros! ¡Es un nuevo estudiante! Te enseñaré encantado todo lo que sé cuando tu habilidad sea algo mejor. Vete a hablar con Gretta Bueneje, ¿vale? Está justo allí. Te pondrá en marcha en un abrir y cerrar de ojos."] = "10d29ce6d81dc4cf54ce10f28a538a8b",
		["Tu habilidad está mejorando mucho. Pronto, podrás abrir tu propia tienda de cuero. Me vendrá bien la ayuda, $n. Mis manos son rápidas, ¡pero con un límite! ¡Hay demasiado trabajo que hacer!"] = "84eac8cc8416941453343ffa518cb882",
	},
	[5130] = {
		["Sí, creo que serías un buen líder. ¿Estás aquí para organizar una hermandad que luche por la Alianza?"] = "f775a0450139eacb7f76a973d4915e00",
	},
	[5141] = {
