	[6766] = {
		["Gritos. Al Maestro Ravenholdt no le gustan los gritos."] = "7c18a505d74d7f81d3aa7e4a1fdefca5",
		["La Hermandad está formada por un grupo de necios, desorganizados, inútiles y vagos..."] = "2d46251ef009b85c2f7a0d08c926ed85",
		["Creo que Simone te estaba buscando antes, $n. ¿Ya has hablado con ella?"] = "d519fc238c0d5762c8390aa9c05d3188",
		["La Mansión Ravenholdt no te reconoce, $c."] = "e414479d7e112a24e4ee47c568f2914a",
		["Hola, $c. ¿Ya has hablado con Fahrad?"] = "5fc8a171cfb31942883d032ece558b20",
		["Es un honor verte de nuevo, $n."] = "0554addc6a4f76eb2e7ded959562d585",
		["Vigila tu espalda."] = "81d62566a55e8b5a5e0eb06e933d7a75",
		["Me alegra verte de nuevo, $n."] = "f425284ed646293e04e52dadcab348c5",
		["Tu astucia ha aumentado en gran medida, $n."] = "21bb13a7f298a61dbf47d64106d4e6ac",
	},
	[6771] = {
		["Salir de aquí sin una espada clavada en tu espalda o veneno corriendo por tus venas, sería un gran logro."] = "b56f7d7e17228c7846fd0614b535f631",
		["Deberías hablar con Ganapiedra. Creo que está buscando ladrones de tu talento."] = "6c7ad021c0414bbc450d1003829fa86b",
		["Realmente te envidio, $n. Haces un trabajo impresionante."] = "d6853e06cead9ccc1834d2216de22df7",
		["¿Osas poner el pie en la Mansión Ravenholdt, babosa?"] = "356d2f6aeda9087735082d9d27eccbf0",
		["Lo estás haciendo muy bien, $n. He oído muchos halagos..."] = "e5da524ba41d32170463455cafed48e5",
		["Maravilloso. Simplemente maravilloso. Eres una inspiración para todos nosotros, $n."] = "043d2239097f1a9dd04f652e7f01f075",
	},
