	[15798] = {
		["Estudiar y entender a los Colosos nos dará una valiosa ventaja sobre los qiraji."] = "ca9c2a76280fa526355a744dfbdacd34",
	},
	[15799] = {
		["¡Tenemos que averiguar qué les dan de comer los qiraji a esos monstruos! ¡Mira qué tamaño tienen!"] = "392d38d469784b0930ac72d8954f8d8e",
	},
	[15864] = {
		["Honrar a tus ancestros es honrar a tu cultura y a tu pueblo, $c. Por ello, las monedas de linaje son un medio tangible de reconocer a aquellos que eligen seguir el venerable camino del respeto.$B$BDurante la celebración del Festival Lunar, tendrás la oportunidad de honrar a muchos Ancestros. Cuando lo hagas, obtendrás las monedas de linaje. Tráeme las monedas y recompensaré tu diligencia con una selección de objetos únicos."] = "5ff684abf73ab59dca0e0d04d8c6f804",
		["Augurio descansa en las profundidades del Lago Elune'ara pero puede ser invocado desde la orilla sudeste, cerca del Túmulo de Tempestira. Allí encontrarás unos lanzacohetes muy especiales...$B$BLanza varios de tus cohetes y aparecerán los esbirros de Augurio. Si continúas lanzando cohetes, unas tres docenas aproximadamente, o si enciendes velas de Elune ante sus esbirros, pronto se despertará."] = "8380da37ec60070f5cc0417fd12e3bc6",
	},
	[15871] = {
		["Ha llegado la hora de un nuevo año y la luna brilla con fuerza.$B$BHa llegado la hora... de que los ancestros se despierten."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
		["El ancestro Filoveloz vaga por los caminos de Darnassus en lo alto de Teldrassil."] = "7b97edf23dc2c013612ec1169de003d7",
		["Puedes encontrar al ancestro Rugidomazo dentro de las murallas de Ventormenta."] = "24e765cdee4370c4b56804eb47e7701f",
		["El ancestro Pozo de Oro se encuentra en la aldea de Kharanos en Dun Morogh."] = "11ccf478d11d91ad3de1ce0965dd1e7c",
		["El ancestro Vetaferro vive en la Cueva Tizonegro en La Garganta de Fuego."] = "6954eeb9a527a8cef8cc62722874280a",
	},
	[15903] = {
		["\"Ha hecho un buen trabajo reuniendo material para la guerra\", dijeron, \"se merece un ascenso\". Lo que realmente querían decir es \"¡Está emplazado al lado de una colmena de bichos en Silithus con un montón de enanos sudorosos, Carnes!\"$B$B¡Gracias por el ascenso, Capitán!"] = "668e49c17df4b9aa59370244f97c3f6a",
	},
	[15905] = {
		["¡Bien $ghallado, amigo:hallada, amiga;!"] = "229605db995a9c242cc65986e5928a1b",
		["Tras los fuegos artificiales, sacarán copas para que podamos brindar."] = "6d7a0a461e2650661f34cbb62df4a64c",
		["No sé que hay en estos barriles ¡pero sabe a gloria!"] = "73bf520ba54e6d1e7f123875ac134dc2",
		["¡No te vayas si no te quieres perder el siguiente espectáculo de fuegos artificiales! Empieza a las 18.00. ¡Son a cada hora en punto!"] = "9e44a7a2990575244bfb03e10d9172dd",
		["No me vendría mal un beso. ¿Sabes dónde podría conseguir uno?"] = "4bf540b1bbdebcaec03285d831690899",
	},
	[15906] = {
