	},
	[15907] = {
		["¡Ave, $c! ¡Te doy la bienvenida a la fiesta!"] = "82e1f388e3d1053dc0d340f63090e225",
		["He oído que tras el espectáculo de fuegos artificiales, pondrán copas en las mesas. ¡Y podremos hacer unos buenos brindis!"] = "ed962dfa7d7188507f9a08ba0eb16209",
		["¡Los barriles están llenos de un brebaje muy fuerte! ¡Bebe, $gamigo:amiga; y diviértete!"] = "06f49d9f9d5fb1edcf209836d4309855",
		["¡A las 18.00 echarán fuegos artificiales desde el risco más alto!"] = "c5f7e2df05ba63b220570cf049a0ae7a",
		["No me vendría mal un beso. ¿Sabes dónde podría conseguir uno?"] = "e46a99e660cce12f8a4292fdb7f7bc29",
	},
	[15908] = {
		["¡Ave, $c! ¡Te doy la bienvenida a la fiesta!"] = "9031ad552c6f16d0a461e40e557acbd7",
		["He oído que tras el espectáculo de fuegos artificiales, pondrán copas en las mesas. ¡Y podremos hacer unos buenos brindis!"] = "c6b790a30cea1e9602b2204c2fdef80a",
		["¡Los barriles están llenos de un brebaje muy fuerte! ¡Bebe, $gamigo:amiga; y diviértete!"] = "a1266790d643e961d1a1d9572db705d7",
