	[16439] = {
		["Al fin ha desaparecido la maldición. Gracias, valiente."] = "60139c1e8304893e783a877f2adadf63",
		["¿Quieres decir que no lo sabes? La espada que llevas a tu espalda se conoce como Crematoria, nombre de su dueño original."] = "aff37574b814f55f881169f5208b9e95",
		["Eso es, el alto señor Mograine: uno de los fundadores de la orden de la Cruzada Escarlata. Un caballero de una fe y pureza inquebrantables, Mograine sería traicionado por su propio hijo y derrotado por las tropas de Kel'Thuzad en Stratholme. Así es como llegué hasta aquí..."] = "4e974e3350b6c509820ed806a61f8cec",
	},
	[16458] = {
		["Tu cuerpo parece desfallecido y tu espíritu agotado. Descansa bajo nuestro techo y deja que Elune inspire tus sueños."] = "88ed28bad52992326e81df54efce5146",
		["Yo no, pero muchos por ahí sí buscan amor. ¡Deberías comprarme pruebas de amor, echarte un poco de colonia o perfume y pasar a su lado!"] = "3334d2c3be49af24ec80966cd3044afb",
